const parseFood = (raw, pre, d) => raw.split('\n').map((l, i) => {
  const a = l.split('|'), u = a[5] ? { n: a[5], g: +a[6] } : null;
  return { id: pre + i, name: a[0], k: +a[1], p: +a[2], f: +a[3], c: +a[4], u, d: d || (a[7] || '').includes('d'), h: (a[7] || '').includes('h') };
});
const FOODS = parseFood(FOOD_RAW, 'b', false).concat(parseFood(DRINK_RAW, 'd', true));

const MEALS = ['Завтрак', 'Обед', 'Ужин', 'Перекус', 'Напитки'];
const MEAL_IC = ['<svg viewBox="0 0 24 24"><path d="M4 8h13v5a5 5 0 01-5 5H9a5 5 0 01-5-5zM17 9h1.5a2.5 2.5 0 010 5H17M8 3v2M12 3v2"/></svg>',
  '<svg viewBox="0 0 24 24"><path d="M3 12h18a9 9 0 01-18 0zM8 8c0-2 2-2 2-4M13 8c0-2 2-2 2-4"/></svg>',
  '<svg viewBox="0 0 24 24"><path d="M4 11h16v3a6 6 0 01-6 6h-4a6 6 0 01-6-6zM7 7l2-3M12 7l2-3"/></svg>',
  '<svg viewBox="0 0 24 24"><path d="M5 20c8 1 15-5 14-14-6 0-12 3-14 9M5 20c1-4 3-7 7-9"/></svg>',
  '<svg viewBox="0 0 24 24"><path d="M6 4h12l-1.4 15a2 2 0 01-2 1.8H9.4a2 2 0 01-2-1.8zM6.6 10h10.8"/></svg>'];

const nutPace = [['l10', 'Бережно', 'дефицит около 10%', -0.10], ['l15', 'Оптимально', 'дефицит около 15%', -0.15], ['l20', 'Быстро', 'дефицит около 20%, для опытных', -0.20], ['keep', 'Держать вес', 'без дефицита и профицита', 0], ['g10', 'Набор массы', 'профицит около 10%', 0.10]];
const nutCfg = () => Object.assign({ age: 0, pace: '', kcal: 0, addTrain: false }, store.get('nut', {}));
const pn = s => { const v = parseFloat(String(s).replace(',', '.')); return isFinite(v) && v >= 0 ? v : 0; };
const r1 = x => Math.round(x * 10) / 10;
const fkey = d => dkey(d.getTime ? d.getTime() : d);
const dayLog = k => { const l = store.get('food:' + k, []); let ch = false; l.forEach(e => { const d = decEnt(e.name); if (d !== e.name) { e.name = d; ch = true; } }); if (ch) store.set('food:' + k, l); return l; };
const saveLog = (k, l) => store.set('food:' + k, l);
const decEnt = s => { s = String(s == null ? '' : s); if (!/&[#a-z0-9]+;/i.test(s)) return s; const t = document.createElement('textarea'); t.innerHTML = s; return t.value; };
const customFoods = () => { const l = store.get('foods', []); let ch = false; l.forEach(f => { const d = decEnt(f.name); if (d !== f.name) { f.name = d; ch = true; } }); if (ch) store.set('foods', l); return l; };
const allFoods = () => customFoods().concat(FOODS);
const foodById = id => allFoods().find(f => f.id === id);
let fdate = '';
const fa = { meal: 0, tab: 'pop', q: '' };

function nutGoal(P0, C0) {
  const P = P0 || profile(), C = C0 || nutCfg(), male = P.gender !== 'female', age = C.age || 25;
  const bmr = Math.round(10 * P.w + 6.25 * P.h - 5 * age + (male ? 5 : -161));
  const pal = [1.2, 1.375, 1.55][P.act] || 1.2, tdee = Math.round(bmr * pal);
  const delta = P.goal - P.w, pace = C.pace || (delta <= -2 ? 'l15' : delta >= 2 ? 'g10' : 'keep');
  const adj = (nutPace.find(x => x[0] === pace) || nutPace[3])[3];
  let kcal = C.kcal > 0 ? Math.round(C.kcal) : Math.round(tdee * (1 + adj) / 10) * 10;
  if (C.chef && !(C.kcal > 0)) kcal = Math.round(kcal * 1.1 / 10) * 10;
  const floor = male ? 1400 : 1200, low = !C.kcal && kcal < floor; if (low) kcal = floor;
  const p = Math.round(P.w * (adj < 0 ? 2 : 1.8)), f = Math.round(kcal * 0.28 / 9), c = Math.max(0, Math.round((kcal - p * 4 - f * 9) / 4));
  return { bmr, tdee, kcal, p, f, c, pace, low };
}
const sumLog = l => l.reduce((s, e) => { s.k += e.k; s.p += e.p; s.f += e.f; s.c += e.c; return s; }, { k: 0, p: 0, f: 0, c: 0 });
const fmt0 = n => Math.round(n).toLocaleString('ru-RU');
const fdateObj = k => { const [y, m, d] = k.split('-').map(Number); return new Date(y, m - 1, d); };
const shiftDay = (k, n) => { const d = fdateObj(k); d.setDate(d.getDate() + n); return fkey(d); };
function dayLabel(k) {
  const t = fkey(new Date());
  if (k === t) return 'Сегодня'; if (k === shiftDay(t, -1)) return 'Вчера'; if (k === shiftDay(t, 1)) return 'Завтра';
  return fdateObj(k).toLocaleDateString('ru-RU', { weekday: 'short', day: 'numeric', month: 'short' });
}
function toast(t, sub, act) {
  const old = document.querySelector('.toast'); if (old) old.remove();
  const el = document.createElement('div'); el.className = 'toast' + (act ? ' act' : ''); el.innerHTML = `<b>${esc(t)}</b>${sub ? '<small>' + esc(sub) + '</small>' : ''}${act ? `<button class="tund">${esc(act.label)}</button>` : ''}`;
  document.body.appendChild(el); const T = act ? 5000 : 1800; setTimeout(() => el.classList.add('hide'), T); setTimeout(() => el.remove(), T + 500);
  if (act) el.querySelector('.tund').onclick = () => { el.remove(); act.fn(); };
}
const waterManual = k => store.get('fw:' + k, 0);
const isDrink = e => e.meal === 4 || !!e.d || !!(foodById(e.fid) || {}).d;
const isWet = e => e.h !== undefined ? !!e.h : !!(foodById(e.fid) || {}).h;
const waterAuto = k => Math.round(dayLog(k).reduce((a, e) => a + (isWet(e) ? e.g || 0 : 0), 0));
const waterDay = k => waterManual(k) + waterAuto(k);
const waterGoal = () => Math.max(1500, Math.round(profile().w * 30 / 100) * 100);
function addWater(ml) { store.set('fw:' + fdate, Math.max(0, waterManual(fdate) + ml)); return waterDay(fdate); }
const sleepDay = k => store.get('fz:' + k, 0);
const SLEEP_GOAL = 480;
const fmtSleep = m => Math.floor(m / 60) + ' ч ' + (m % 60 ? m % 60 + ' мин' : '').trim();
const stepsDay = k => store.get('fs:' + k, 0);
const STEP_GOAL = 10000;
const stepKcal = s => Math.round(s * profile().w * 0.0005);
const bodyFat = (P, age) => { if (!(age > 0)) return 0; const bmi = P.w / Math.pow(P.h / 100, 2), v = 1.2 * bmi + 0.23 * age - (P.gender === 'female' ? 0 : 10.8) - 5.4; return Math.max(4, Math.min(60, Math.round(v * 10) / 10)); };
const foodRefresh = () => location.hash === '#fmeal' ? viewMeal(true) : viewFood(true);
const trainKcal = k => hist().filter(h => dkey(h.ts) === k).reduce((s, h) => s + (h.kcal || 0), 0);

function viewFood(keep) {
  if (!fdate) fdate = fkey(new Date());
  const C = nutCfg(), y = keep ? window.scrollY : 0;
  if (!C.birth && !sessionStorage.getItem('tr-nut')) { try { sessionStorage.setItem('tr-nut', '1'); } catch (e) { } return nutWizard(false); }
  const G = nutGoal(), log = dayLog(fdate), S = sumLog(log), tk = trainKcal(fdate), sk = stepKcal(stepsDay(fdate)), budget = G.kcal + (C.addTrain ? tk + sk : 0), left = budget - S.k;
  const R = 54, L = 2 * Math.PI * R, share = Math.min(1, S.k / Math.max(1, budget));
  const bar = (n, v, t, col) => `<div class="mb"><div><span>${n}</span><b>${fmt0(v)} / ${t} г</b></div><i><u style="width:${Math.min(100, v / Math.max(1, t) * 100)}%;background:${col}"></u></i></div>`;
  const tiles = MEALS.map((m, i) => { const s = sumLog(log.filter(e => i === 4 ? isDrink(e) : e.meal === i)); return `<div class="mt" data-mo="${i}"><span class="mi">${MEAL_IC[i]}</span><button class="mp" data-add="${i}" aria-label="Добавить: ${m}">${I.plus}</button><b>${m}</b><small>${fmt0(s.k)} ккал</small></div>`; }).join('') + `<div class="mt wtl" id="wtile"><span class="mi wi2">${WI.drop}</span><button class="mp" id="wadd" aria-label="Добавить 50 мл воды">${I.plus}</button><b>Вода</b><small>${fmt0(waterDay(fdate))} / ${fmt0(waterGoal())} мл</small><i class="wbar"><u style="width:${Math.min(100, waterDay(fdate) / waterGoal() * 100)}%"></u></i></div>`;
  const fmode = store.get('fmode', 'time'), row = e => `<button class="fe" data-fe="${e.id}"><span class="mi sm">${MEAL_IC[e.meal]}</span><div><b>${esc(e.name)}</b><small>${fmode === 'time' ? timeT(e) + ' · ' : ''}${e.g ? fmt0(e.g) + ' г · ' : ''}Б ${num(r1(e.p))} · Ж ${num(r1(e.f))} · У ${num(r1(e.c))}</small></div><em>${fmt0(e.k)}<small>ккал</small></em></button>`;
  const timeT = e => new Date(e.ts).toLocaleTimeString('ru-RU', { hour: '2-digit', minute: '2-digit' });
  const sorted = log.slice().sort((a, b) => a.ts - b.ts), entries = sorted.length;
  const diaryHtml = fmode === 'meal' ? MEALS.map((m, mi) => { const l = sorted.filter(e => e.meal === mi); if (!l.length) return ''; const s = sumLog(l); return `<div class="fgh"><b>${m}</b><span>${fmt0(s.k)} ккал</span></div><div class="flog">${l.map(row).join('')}</div>`; }).join('') : `<div class="flog">${sorted.map(row).join('')}</div>`
  const days = [...Array(7)].map((_, i) => shiftDay(fkey(new Date()), i - 6));
  const tot = days.map(d => sumLog(dayLog(d)).k), mx = Math.max(G.kcal * 1.15, ...tot, 1), filled = tot.filter(x => x > 0), avg = filled.length ? Math.round(filled.reduce((a, b) => a + b, 0) / filled.length) : 0;
  view(`<div class="screen has-nav">
    <div class="bar"><button class="rbtn" id="fcal" aria-label="Выбрать день">${I.hist}</button><h1>Питание<small>${esc(fdateObj(fdate).toLocaleDateString('ru-RU', { weekday: 'long', day: 'numeric', month: 'long' }))}</small></h1><button class="rbtn" id="fset" aria-label="Настройки питания">${I.gear}</button></div>
    <div class="fdays"><button data-fd="-1" aria-label="Предыдущий день">${I.back}</button><b>${dayLabel(fdate)}</b><button data-fd="1" class="nx" aria-label="Следующий день">${I.back}</button></div>
    <div class="fcard"><div class="fring"><svg viewBox="0 0 130 130"><circle cx="65" cy="65" r="${R}" class="bg"/><circle cx="65" cy="65" r="${R}" class="fg ${left < 0 ? 'over' : ''}" stroke-dasharray="${(L * share).toFixed(1)} ${L.toFixed(1)}" transform="rotate(-90 65 65)"/></svg><div><b>${fmt0(Math.abs(left))}</b><small>${left < 0 ? 'сверх нормы' : 'осталось'}</small></div></div>
      <div class="fmac">${bar(MAC.p.i + 'Белки', S.p, G.p, MAC.p.c)}${bar(MAC.f.i + 'Жиры', S.f, G.f, MAC.f.c)}${bar(MAC.c.i + 'Углеводы', S.c, G.c, MAC.c.c)}<div class="ft">съедено ${fmt0(S.k)} из ${fmt0(budget)} ккал${C.addTrain && tk + sk ? ' (активность +' + fmt0(tk + sk) + ')' : ''}</div></div></div>
    <div class="mtiles">${tiles}</div>
    <div class="stp2"><button class="stp" id="stile"><span class="mi wi2 st">${WI.steps}</span><div><b>Шаги</b><small>${fmt0(stepsDay(fdate))} / ${fmt0(STEP_GOAL)}</small><i class="wbar"><u style="width:${Math.min(100, stepsDay(fdate) / STEP_GOAL * 100)}%"></u></i></div></button><button class="stp" id="ztile"><span class="mi wi2 zz">${WI.sleep}</span><div><b>Сон</b><small>${sleepDay(fdate) ? fmtSleep(sleepDay(fdate)) : 'не записан'} / 8 ч</small><i class="wbar sl"><u style="width:${Math.min(100, sleepDay(fdate) / SLEEP_GOAL * 100)}%"></u></i></div></button></div>
    ${supTile()}
    ${tk + sk && !C.addTrain ? `<div class="note">Тренировки и шаги за день: примерно ${fmt0(tk + sk)} ккал. В настройках питания можно прибавлять их к норме.</div>` : ''}
    <div class="sh">${I.food.replace('<svg', '<svg class="shi"')}Дневник</div>
    <div class="seg wide fmode"><button data-fm="time" class="${fmode === 'time' ? 'on' : ''}">Хронология</button><button data-fm="meal" class="${fmode === 'meal' ? 'on' : ''}">По приёмам</button></div>
    ${entries ? diaryHtml : '<div class="empty small"><img class="fmas" src="img/m_food.webp" alt="" onerror="this.remove()"><br>Пока ничего не добавлено. Нажми плюс у нужного приёма пищи.</div>'}
    <div class="sh">Неделя</div>
    <div class="wb"><div class="wbars">${tot.map((t, i) => `<div class="wc ${days[i] === fdate ? 'on' : ''}" data-wd="${days[i]}"><i style="height:${Math.max(3, t / mx * 100)}%" class="${t > G.kcal * 1.05 ? 'over' : ''}"></i><span>${fdateObj(days[i]).toLocaleDateString('ru-RU', { weekday: 'short' })}</span></div>`).join('')}<u style="bottom:${(G.kcal / mx * 100).toFixed(1)}%"></u></div><div class="ft">Среднее за дни с записями: ${avg ? fmt0(avg) + ' ккал' : 'нет данных'}. Линия: твоя норма ${fmt0(G.kcal)}.</div></div>
    ${XT.wlink()}
    <div class="hint">Калорийность продуктов примерная, по справочным таблицам. Это ориентир, а не медицинская рекомендация.</div>
    ${nav('food')}</div>`);
  if (keep) window.scrollTo(0, y);
  $('#fset').onclick = () => nutWizard(true);
  $('#fcal').onclick = () => openCalSheet(); void (() => nSheet(`<h3>Выбрать день</h3><div class="opt"><input type="date" id="fdt" class="dateinp" value="${fdate}" max="${shiftDay(fkey(new Date()), 30)}"></div><button class="big" id="fdok">Показать</button>`, () => { $('#fdok').onclick = () => { const v = $('#fdt').value; if (v) { fdate = v; closeSheet(); viewFood(); } }; }));
  document.querySelectorAll('[data-fd]').forEach(b => b.onclick = () => { fdate = shiftDay(fdate, +b.dataset.fd); viewFood(true); });
  document.querySelectorAll('[data-wd]').forEach(b => b.onclick = () => { fdate = b.dataset.wd; viewFood(true); });
  document.querySelectorAll('[data-add]').forEach(b => b.onclick = () => { fa.meal = +b.dataset.add; fa.tab = 'pop'; fa.q = ''; go('#fadd'); });
  $('#wadd').onclick = e => { e.stopPropagation(); const v = addWater(50); viewFood(true); toast('Вода +50 мл', fmt0(v) + ' из ' + fmt0(waterGoal()) + ' мл'); };
  $('#wtile').onclick = openWater;
  document.querySelectorAll('[data-fe]').forEach(b => b.onclick = () => openEntry(b.dataset.fe));
  document.querySelectorAll('[data-fm]').forEach(b => b.onclick = () => { store.set('fmode', b.dataset.fm); viewFood(true); });
  document.querySelectorAll('[data-mo]').forEach(t => t.onclick = e => { if (e.target.closest('.mp')) return; fa.meal = +t.dataset.mo; go('#fmeal'); });
  $('#stile').onclick = openSteps;
  $('#ztile').onclick = openSleep;
  $('#sptile').onclick = openSup;
}

function openNutSetup(first) {
  const P = profile(), C = nutCfg(), cur = Object.assign({}, C), G0 = nutGoal();
  nSheet(`<h3>${first ? 'Настроим норму питания' : 'Настройки питания'}</h3>
    <div class="opt"><div>Возраст<small>нужен для расчёта обмена веществ</small></div><div class="nin"><input id="nage" type="number" inputmode="numeric" value="${C.age || ''}" placeholder="25"><span>лет</span></div></div>
    <div class="glab">Темп</div><div class="grp">${nutPace.map(([k, t, d]) => `<button class="opt pick ${(C.pace || G0.pace) === k ? 'on' : ''}" data-np="${k}"><div>${t}<small>${d}</small></div></button>`).join('')}</div>
    <div class="opt"><div>Своя норма<small>0 = считать автоматически</small></div><div class="nin"><input id="nkc" type="number" inputmode="numeric" value="${C.kcal || ''}" placeholder="авто"><span>ккал</span></div></div>
    <div class="opt"><div>Щедрый повар<small>плюс 10% к норме: запас на порции «на глаз» <span class="chq" data-chefi>Что это?</span></small></div><button class="sw ${C.chef ? 'on' : ''}" id="nchef" role="switch" aria-checked="${!!C.chef}"></button></div>
    <div class="opt"><div>Прибавлять калории тренировок и шагов<small>к норме на день</small></div><button class="sw ${C.addTrain ? 'on' : ''}" id="ntr" role="switch" aria-checked="${!!C.addTrain}"></button></div>
    <div class="opt"><small id="nsum">Рост, вес и активность берутся из профиля. Сейчас: обмен ${fmt0(G0.bmr)}, расход ${fmt0(G0.tdee)}, норма ${fmt0(G0.kcal)} ккал.</small></div>
    <button class="big sec" id="nre">Пройти анкету заново</button>
    <button class="big" id="nok">Сохранить</button>`, () => {
    $('#nre').onclick = () => { closeSheet(); nutWizard(true); };
    document.querySelectorAll('[data-np]').forEach(b => b.onclick = () => { cur.pace = b.dataset.np; document.querySelectorAll('[data-np]').forEach(x => x.classList.toggle('on', x === b)); });
    $('#nchef').onclick = e => { cur.chef = !cur.chef; e.currentTarget.classList.toggle('on', cur.chef); e.currentTarget.setAttribute('aria-checked', String(cur.chef)); };
    $('#ntr').onclick = e => { cur.addTrain = !cur.addTrain; e.currentTarget.classList.toggle('on', cur.addTrain); e.currentTarget.setAttribute('aria-checked', String(cur.addTrain)); };
    $('#nok').onclick = () => { const a = Math.round(pn($('#nage').value)); if (!(a >= 10 && a <= 100)) { $('#nage').focus(); return; } cur.age = a; cur.kcal = Math.round(pn($('#nkc').value)); store.set('nut', cur); closeSheet(); viewFood(); };
  });
}

function nSheet(h, b) { return openSheet(h, b); }

/* ---- добавки ---- */
const supList = () => store.get('sup', []);
const supDay = k => store.get('fsu:' + k, {});
const SUP_SUG = ['Креатин', 'Витамин D', 'Омега-3', 'Магний', 'Протеин', 'Мультивитамины'];
function supStat(k) { const l = supList(), d = supDay(k); return { plan: l.reduce((a, x) => a + x.t, 0), done: l.reduce((a, x) => a + Math.min(d[x.id] || 0, x.t), 0) }; }
function supWeek(keys) { const l = supList(); if (!l.length) return { has: false, plan: 0, done: 0 }; let plan = 0, done = 0; keys.forEach(k => { const s = supStat(k); plan += s.plan; done += s.done; }); return { has: true, plan, done }; }
function supTile() {
  const l = supList(), s = supStat(fdate);
  return `<button class="stp" id="sptile"><span class="mi wi2 st">${WI.pill}</span><div><b>Добавки</b><small>${l.length ? s.done + ' / ' + s.plan + ' приёмов' : 'добавь свои: креатин, витамин D и другое'}</small>${l.length ? `<i class="wbar"><u style="width:${s.plan ? Math.min(100, s.done / s.plan * 100) : 0}%"></u></i>` : ''}</div></button>`;
}
function openSup() {
  let add = { n: '', t: 1 };
  const draw = () => {
    const l = supList(), d = supDay(fdate), el = $('#suplist'); if (!el) return;
    el.innerHTML = l.length ? l.map(x => { const c = d[x.id] || 0; return `<div class="sup"><div class="sn"><b>${esc(x.n)}</b><small>${x.t === 1 ? '1 раз в день' : x.t + ' раза в день'}</small></div><div class="sc"><button data-sm="${x.id}" aria-label="Минус">−</button><b class="${c >= x.t ? 'ok' : ''}">${c}</b><button data-sp="${x.id}" aria-label="Плюс">+</button></div><button class="sx" data-sd="${x.id}" aria-label="Удалить добавку">${I.close}</button></div>`; }).join('') : '<div class="empty small">Добавок пока нет. Выбери из списка ниже или впиши свою.</div>';
    el.querySelectorAll('[data-sm],[data-sp]').forEach(b => b.onclick = () => { const id = b.dataset.sm || b.dataset.sp, dd = supDay(fdate); dd[id] = Math.max(0, (dd[id] || 0) + (b.dataset.sp ? 1 : -1)); store.set('fsu:' + fdate, dd); draw(); });
    el.querySelectorAll('[data-sd]').forEach(b => b.onclick = () => { store.set('sup', supList().filter(x => x.id !== b.dataset.sd)); draw(); });
    document.querySelectorAll('[data-ss]').forEach(b => b.classList.toggle('on', b.dataset.ss === add.n));
  };
  nSheet(`<h3>Добавки</h3><div id="suplist"></div>
    <div class="glab">Добавить</div>
    <div class="wq sugs">${SUP_SUG.map(x => `<button data-ss="${esc(x)}">${x}</button>`).join('')}</div>
    <div class="opt"><input id="supn" type="text" placeholder="Название" maxlength="30" autocomplete="off"></div>
    <div class="opt"><div>Раз в день</div><div class="seg" id="supt">${[1, 2, 3, 4].map(x => `<button data-st="${x}" class="${x === 1 ? 'on' : ''}">${x}</button>`).join('')}</div></div>
    <button class="big sec" id="supadd">Добавить в список</button><button class="big" id="supok">Готово</button>`, () => {
    draw();
    document.querySelectorAll('[data-ss]').forEach(b => b.onclick = () => { add.n = b.dataset.ss; $('#supn').value = add.n; draw(); });
    $('#supn').oninput = e => { add.n = e.target.value; draw(); };
    document.querySelectorAll('[data-st]').forEach(b => b.onclick = () => { add.t = +b.dataset.st; document.querySelectorAll('[data-st]').forEach(x => x.classList.toggle('on', x === b)); });
    $('#supadd').onclick = () => { const n = $('#supn').value.trim(); if (!n) { $('#supn').focus(); return; } const l = supList(); if (l.some(x => x.n.toLowerCase() === n.toLowerCase())) { toast('Уже в списке', n); return; } l.push({ id: 's' + Date.now().toString(36), n, t: add.t }); store.set('sup', l); add = { n: '', t: 1 }; $('#supn').value = ''; draw(); };
    $('#supok').onclick = () => { closeSheet(); viewFood(true); };
  });
}

/* ---- шаблоны приёмов пищи ---- */
const TPL_N = ['Мой завтрак', 'Мой обед', 'Мой ужин', 'Мой перекус', 'Мои напитки'];
const tplList = () => store.get('ftpl', []);
function openTpl() {
  const m = fa.meal, cur = dayLog(fdate).filter(e => m === 4 ? isDrink(e) : e.meal === m);
  const draw = () => {
    const l = tplList(), el = $('#tpllist'); if (!el) return;
    el.innerHTML = l.length ? l.map(t => { const s = sumLog(t.items); return `<div class="tpl"><button class="tpb" data-tu="${t.id}"><b>${esc(t.name)}</b><small>Продуктов: ${t.items.length} · ${fmt0(s.k)} ккал · Б ${num(r1(s.p))} Ж ${num(r1(s.f))} У ${num(r1(s.c))}</small></button><button class="sx" data-td="${t.id}" aria-label="Удалить шаблон">${I.close}</button></div>`; }).join('') : '<div class="empty small">Шаблонов пока нет. Добавь продукты в приём пищи и сохрани их как шаблон.</div>';
    el.querySelectorAll('[data-tu]').forEach(b => b.onclick = () => {
      const t = tplList().find(x => x.id === b.dataset.tu); if (!t) return;
      const lg = dayLog(fdate), base = Date.now();
      t.items.forEach((e, i) => lg.push(Object.assign({}, e, { id: base + '' + i + Math.floor(Math.random() * 1000), ts: base + i, meal: m === 4 ? e.meal : m })));
      saveLog(fdate, lg); fa.added = (fa.added || 0) + 1; closeSheet(); toast(t.name, MEALS[m] + ': добавлено ' + t.items.length);
      if (location.hash === '#fmeal') viewMeal(true); else if (location.hash === '#fadd') { const c = $('#fcnt'); if (c) c.textContent = fa.added; else viewFoodAdd(); }
    });
    el.querySelectorAll('[data-td]').forEach(b => b.onclick = () => { store.set('ftpl', tplList().filter(x => x.id !== b.dataset.td)); draw(); });
  };
  nSheet(`<h3>Мои приёмы пищи</h3><div id="tpllist"></div>
    ${cur.length ? `<div class="glab">Сохранить текущий приём, записей: ${cur.length}</div><div class="opt"><input id="tpln" type="text" placeholder="Название, например: мой завтрак" maxlength="40" value="${esc(TPL_N[m])}" autocomplete="off"></div><button class="big sec" id="tpls">Сохранить как шаблон</button>` : ''}
    <button class="big" id="tpld">Закрыть</button>`, () => {
    draw();
    if ($('#tpls')) $('#tpls').onclick = () => { const n = $('#tpln').value.trim() || TPL_N[m]; const items = cur.map(e => { const c = Object.assign({}, e); delete c.id; delete c.ts; return c; }); const l = tplList(); l.unshift({ id: 't' + Date.now().toString(36), name: n, items }); store.set('ftpl', l.slice(0, 30)); toast('Шаблон сохранён', n); draw(); };
    $('#tpld').onclick = closeSheet;
  });
}
function openWater() {
  nSheet(`<h3>Вода</h3><div class="pbig"><b id="wv">0</b><small>мл</small><div id="wg"></div></div>
    <div class="wq">${[50, 100, 250, 500].map(x => `<button data-wq="${x}">+${x}</button>`).join('')}</div>
    <div class="wq"><button data-wq="-50">−50</button><button data-wq="0" id="wz0">Сбросить</button></div>
    <button class="big" id="wdone">Готово</button>`, () => {
    const show = () => { const v = waterDay(fdate), au = waterAuto(fdate); $('#wv').textContent = fmt0(v); $('#wg').textContent = 'норма ' + fmt0(waterGoal()) + ' мл · ' + Math.round(v / waterGoal() * 100) + '%' + (au ? '\nвручную ' + fmt0(v - au) + ' + из напитков ' + fmt0(au) : ''); };
    show();
    document.querySelectorAll('[data-wq]').forEach(b => b.onclick = () => { const d = +b.dataset.wq; if (b.id === 'wz0') store.set('fw:' + fdate, 0); else addWater(d); show(); });
    $('#wdone').onclick = () => { closeSheet(); viewFood(true); };
  });
}
function openEntry(id) {
  const l = dayLog(fdate), e = l.find(x => x.id === id); if (!e) return;
  let meal = e.meal;
  nSheet(`<h3>${esc(e.name)}</h3>
    ${e.b ? `<div class="opt"><div>Количество, г</div><div class="nin"><input id="eg" type="number" inputmode="decimal" value="${e.g}"><span>г</span></div></div>` : ''}
    <div class="opt"><small id="esum"></small></div>
    <div class="grp"><div class="segrow"><div class="seg wide">${MEALS.map((m, i) => `<button data-em="${i}" class="${i === meal ? 'on' : ''}">${m}</button>`).join('')}</div></div></div>
    <button class="big" id="eok">Сохранить</button><button class="big sec" id="ecp">Копировать в другой день</button><button class="big sec" id="edel">Удалить</button>`, () => {
    const calc = () => { if (!e.b) return { k: e.k, p: e.p, f: e.f, c: e.c, g: 0 }; const g = pn($('#eg').value), m = g / 100; return { g, k: e.b[0] * m, p: e.b[1] * m, f: e.b[2] * m, c: e.b[3] * m }; };
    const show = () => { const v = calc(); $('#esum').textContent = `${fmt0(v.k)} ккал · Б ${num(r1(v.p))} · Ж ${num(r1(v.f))} · У ${num(r1(v.c))}`; };
    show(); if ($('#eg')) $('#eg').oninput = show;
    document.querySelectorAll('[data-em]').forEach(b => b.onclick = () => { meal = +b.dataset.em; document.querySelectorAll('[data-em]').forEach(x => x.classList.toggle('on', x === b)); });
    $('#eok').onclick = () => { const v = calc(); if (e.b && !(v.g > 0)) return; Object.assign(e, { g: v.g, k: Math.round(v.k), p: r1(v.p), f: r1(v.f), c: r1(v.c), meal }); saveLog(fdate, l); closeSheet(); foodRefresh(); };
    $('#ecp').onclick = () => openCopy([e]);
    $('#edel').onclick = () => { saveLog(fdate, l.filter(x => x.id !== id)); closeSheet(); foodRefresh(); };
  });
}
function addEntry(o) {
  const l = dayLog(fdate), now = new Date(), t = fdate === fkey(now) ? now.getTime() : fdateObj(fdate).getTime() + 12 * 3600e3 + l.length * 1000;
  l.push(Object.assign({ id: t + '' + Math.floor(Math.random() * 1000), meal: fa.meal, ts: t }, o)); saveLog(fdate, l);
  fa.added = (fa.added || 0) + 1;
  const s = sumLog(l.filter(e => e.meal === fa.meal)); toast(MEALS[fa.meal] + ': ' + fmt0(s.k) + ' ккал', o.name + ' · ' + fmt0(o.k) + ' ккал');
  const cnt = $('#fcnt'); if (cnt) cnt.textContent = fa.added;
}

const norm = s => String(s).toLowerCase().replace(/ё/g, 'е');
function foodList() {
  const fav = store.get('ffav', []), rec = store.get('frecent', []), q = norm(fa.q).trim(), hid = new Set(store.get('fhide', []));
  let list; const dr = fa.meal === 4;
  if (q) { const w = q.split(/\s+/); list = allFoods().filter(f => { const n = norm(f.name) + (window.LANG === 'en' ? ' ' + norm(tr(f.name)) : ''); return w.every(x => n.includes(x)) && (!dr || f.d) && !hid.has(f.id); }); const sc = f => fav.includes(f.id) ? 0 : rec.includes(f.id) ? 1 : 2; list = list.map((f, i) => [f, i]).sort((a, b) => sc(a[0]) - sc(b[0]) || a[1] - b[1]).map(x => x[0]); }
  else if (fa.tab === 'rec') list = rec.map(foodById).filter(Boolean);
  else if (fa.tab === 'fav') list = fav.map(foodById).filter(Boolean);
  else if (fa.tab === 'my') list = customFoods();
  else if (fa.tab === 'dish') list = customFoods().filter(f => f.dish);
  else if (fa.tab === 'freq') list = XT.freq();
  else list = FOODS.filter(f => !!f.d === dr && !hid.has(f.id));
  return list;
}
function foodRow(f) {
  const u = f.u ? ` · 1 ${esc(f.u.n)} ${f.u.g} г` : '';
  const fv = store.get('ffav', []).includes(f.id) ? `<span class="fvm">${I.starOn}</span>` : '';
  return `<div class="fi"><button class="fim" data-fo="${f.id}"><b>${fv}${esc(f.name)}</b><small>${fmt0(f.k)} ккал · БЖУ ${num(r1(f.p))}/${num(r1(f.f))}/${num(r1(f.c))}${u}</small></button><button class="fip" data-fq="${f.id}" aria-label="Добавить">${I.plus}</button></div>`;
}
function viewFoodAdd() {
  if (!fdate) fdate = fkey(new Date());
  view(`<div class="screen">
    <div class="bar"><button class="rbtn" id="fback" aria-label="Назад">${I.back}</button><h1>${MEALS[fa.meal]}<small>${esc(dayLabel(fdate))}${fa.added ? ' · добавлено: <span id="fcnt">' + fa.added + '</span>' : ''}</small></h1><button class="rbtn dn" id="fdn">Готово</button></div>
    <div class="fsearch"><svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="7"/><path d="M20 20l-4-4"/></svg><input id="fq" type="search" placeholder="Найти продукт" value="${esc(fa.q)}" autocomplete="off"><button class="fclr" id="fqx" aria-label="Очистить" hidden><svg viewBox="0 0 24 24"><path d="M7 7l10 10M17 7L7 17"/></svg></button></div>
    <div class="seg wide ftabs">${[['pop', 'Популярное'], ['rec', 'Недавние'], ['fav', 'Избранные'], ['my', 'Свои']].concat(XT.tabs()).map(([k, t]) => `<button data-ft="${k}" class="${fa.tab === k && !fa.q ? 'on' : ''}">${t}</button>`).join('')}</div>
    <div class="fbtns"><button id="fnew">Создать продукт</button><button id="fquick">Только калории</button><button id="ftpl">Шаблоны</button>${XT.dishBtn()}</div>
    <div id="fl" class="flist"></div>
    <button class="fscan" id="fscan" aria-label="Сканировать штрихкод"><svg viewBox="0 0 24 24"><path d="M3 7V5a2 2 0 012-2h2M17 3h2a2 2 0 012 2v2M21 17v2a2 2 0 01-2 2h-2M7 21H5a2 2 0 01-2-2v-2M7 8v8M10.5 8v8M14 8v8M17 8v8"/></svg></button></div>`);
  const draw = () => {
    const l = foodList(), el = $('#fl');
    const nh = store.get('fhide', []).length;
    let top = '';
    if (fa.tab === 'pop' && !fa.q) {
      const hid = new Set(store.get('fhide', [])), dr = fa.meal === 4, ok = f => f && !!f.d === dr && !hid.has(f.id);
      const fv = store.get('ffav', []).map(foodById).filter(ok).slice(0, 5), fvi = new Set(fv.map(f => f.id)), rc = store.get('frecent', []).map(foodById).filter(f => ok(f) && !fvi.has(f.id)).slice(0, 5), used = new Set([...fv, ...rc].map(f => f.id));
      if (fv.length) top += '<div class="fsh">Избранное</div>' + fv.map(foodRow).join('');
      if (rc.length) top += '<div class="fsh">Недавние</div>' + rc.map(foodRow).join('');
      if (top) { top += '<div class="fsh">Все продукты</div>'; l.splice(0, l.length, ...l.filter(f => !used.has(f.id))); }
    }
    el.innerHTML = top + (l.length ? l.slice(0, 120).map(foodRow).join('') + (l.length > 120 ? `<div class="empty small">Показано 120 из ${l.length}. Уточни поиск.</div>` : '') : `<div class="empty small">${fa.q ? 'Ничего не найдено. Создай свой продукт.' : fa.tab === 'rec' ? 'Здесь появятся продукты, которые ты добавлял.' : fa.tab === 'fav' ? 'Открой продукт и отметь звёздочкой.' : 'Своих продуктов пока нет.'}</div>`);
    if (nh && fa.tab === 'pop' && !fa.q) { el.insertAdjacentHTML('beforeend', `<button class="fhid" id="fhid">Скрыто продуктов: ${nh}. Вернуть все</button>`); $('#fhid').onclick = () => { store.set('fhide', []); draw(); toast('Продукты возвращены', ''); }; }
    document.querySelectorAll('[data-ft]').forEach(b => b.classList.toggle('on', b.dataset.ft === fa.tab && !fa.q));
  };
  draw();
  const fqs = () => { $('#fqx').hidden = !$('#fq').value; };
  fqs();
  $('#fq').oninput = e => { fa.q = e.target.value; fqs(); draw(); };
  $('#fqx').onclick = () => { $('#fq').value = ''; fa.q = ''; fqs(); draw(); $('#fq').focus(); };
  $('#fl').onclick = e => {
    const o = e.target.closest('[data-fo]'), q = e.target.closest('[data-fq]');
    if (o) openPortion(o.dataset.fo); else if (q) quickAdd(q.dataset.fq);
  };
  document.querySelectorAll('[data-ft]').forEach(b => b.onclick = () => { fa.tab = b.dataset.ft; fa.q = ''; $('#fq').value = ''; fqs(); draw(); });
  $('#fback').onclick = $('#fdn').onclick = () => { fa.added = 0; go('#food'); };
  $('#fnew').onclick = () => openCustom();
  $('#fquick').onclick = () => openQuick();
  $('#ftpl').onclick = openTpl;
  $('#fscan').onclick = () => XT.scan();
  if ($('#fdish')) $('#fdish').onclick = () => XT.dish();
}
function foodEntry(f, g) { const m = g / 100; return { fid: f.id, name: f.name, g, d: f.d ? 1 : 0, h: f.h ? 1 : 0, b: [f.k, f.p, f.f, f.c], k: Math.round(f.k * m), p: r1(f.p * m), f: r1(f.f * m), c: r1(f.c * m) }; }
function pushRecent(id) { const r = store.get('frecent', []).filter(x => x !== id); r.unshift(id); store.set('frecent', r.slice(0, 30)); }
function quickAdd(id) { const f = foodById(id); if (!f) return; const g = f.u ? f.u.g : 100; addEntry(foodEntry(f, g)); pushRecent(id); }
function openPortion(id) {
  const f = foodById(id); if (!f) return;
  const units = [{ n: 'г', g: 1 }]; if (f.u) units.unshift({ n: f.u.n + ' (' + f.u.g + ' г)', g: f.u.g });
  const isFav = () => store.get('ffav', []).includes(id);
  nSheet(`<h3>${esc(f.name)}<button class="fav2 ${isFav() ? 'on' : ''}" id="pfav" aria-label="В избранное">${isFav() ? I.starOn : I.star}</button></h3>
    <div class="opt"><small>На 100 г: ${fmt0(f.k)} ккал · Б ${num(r1(f.p))} · Ж ${num(r1(f.f))} · У ${num(r1(f.c))}</small></div>
    <div class="pbig"><b id="pk">0</b><small>ккал</small><div id="pm"></div></div>
    ${units.length > 1 ? `<div class="seg wide" id="pus">${units.map((u, k) => `<button data-pu="${k}" class="${k === 0 ? 'on' : ''}">${esc(u.n)}</button>`).join('')}</div>` : ''}
    <div class="pstep"><button id="pdn" aria-label="Меньше">−</button><div class="nin"><input id="pa" type="number" inputmode="decimal" value="${f.u ? 1 : 100}" step="any"><span id="pul">${esc(units[0].n.replace(/ \(.*$/, ''))}</span></div><button id="pup" aria-label="Больше">+</button></div>
    <div class="pchips" id="pch"></div>
    <button class="big" id="pok">Добавить</button>`, () => {
    let calc; const show = () => { const v = calc(); $('#pk').textContent = fmt0(v.k); $('#pm').textContent = `Б ${num(r1(v.p))} · Ж ${num(r1(v.f))} · У ${num(r1(v.c))}${f.u && v.g ? ' · ' + fmt0(v.g) + ' г' : ''}`; };
    let ui = 0; const U = () => units[ui], isG = () => U().g === 1;
    const chips = () => { const L = isG() ? [50, 100, 150, 200, 250] : [1, 2, 3, 4, 5]; $('#pch').innerHTML = L.map(x => `<button data-pc="${x}">${x}${isG() ? ' г' : ''}</button>`).join(''); document.querySelectorAll('[data-pc]').forEach(b => b.onclick = () => { $('#pa').value = b.dataset.pc; show(); }); };
    const setU = k => { ui = k; document.querySelectorAll('[data-pu]').forEach(x => x.classList.toggle('on', +x.dataset.pu === k)); $('#pul').textContent = U().n.replace(/ \(.*$/, ''); $('#pa').value = isG() ? 100 : 1; chips(); show(); };
    const step = d => { const st = isG() ? 10 : 1, v = Math.max(0, Math.round((pn($('#pa').value) + d * st) * 10) / 10); $('#pa').value = v; show(); };
    calc = () => { const g = pn($('#pa').value) * U().g, m = g / 100; return { g, k: f.k * m, p: f.p * m, f: f.f * m, c: f.c * m }; };
    show(); chips(); $('#pa').oninput = show; $('#pdn').onclick = () => step(-1); $('#pup').onclick = () => step(1);
    document.querySelectorAll('[data-pu]').forEach(b => b.onclick = () => setU(+b.dataset.pu));
    $('#pfav').onclick = () => { const l = store.get('ffav', []), i = l.indexOf(id); if (i < 0) l.unshift(id); else l.splice(i, 1); store.set('ffav', l); const on = l.includes(id), b = $('#pfav'); b.classList.toggle('on', on); b.innerHTML = on ? I.starOn : I.star; };
    $('#pok').onclick = () => { const v = calc(); if (!(v.g > 0)) { $('#pa').focus(); return; } addEntry(foodEntry(f, Math.round(v.g * 10) / 10)); pushRecent(id); closeSheet(); };
  });
}
function openCustom(bc) {
  nSheet(`<h3>Новый продукт</h3>${bc ? `<div class="opt"><small>Штрихкод ${esc(bc)} запомнится: при следующем сканировании продукт найдётся сразу.</small></div>` : ''}
    <div class="opt"><div>Название</div><input id="cn" class="tin wide" type="text" placeholder="Например, мой йогурт" autocomplete="off"></div>
    <div class="glab">На 100 г</div>
    <div class="opt"><div>Калории</div><div class="nin"><input id="ck" type="number" inputmode="decimal"><span>ккал</span></div></div>
    <div class="opt"><div>Белки</div><div class="nin"><input id="cp" type="number" inputmode="decimal"><span>г</span></div></div>
    <div class="opt"><div>Жиры</div><div class="nin"><input id="cf" type="number" inputmode="decimal"><span>г</span></div></div>
    <div class="opt"><div>Углеводы</div><div class="nin"><input id="cc" type="number" inputmode="decimal"><span>г</span></div></div>
    <div class="opt"><div>Вес одной штуки<small>необязательно</small></div><div class="nin"><input id="cu" type="number" inputmode="decimal"><span>г</span></div></div>
    <button class="big" id="cok">Сохранить</button>`, () => {
    $('#cok').onclick = () => {
      const name = $('#cn').value.trim(), k = pn($('#ck').value); if (!name) { $('#cn').focus(); return; } if (!(k >= 0) || $('#ck').value === '') { $('#ck').focus(); return; }
      const g = pn($('#cu').value), f = { id: 'c' + Date.now(), name, k, p: pn($('#cp').value), f: pn($('#cf').value), c: pn($('#cc').value), u: g > 0 ? { n: 'шт', g } : null, d: fa.meal === 4 }; if (bc) f.bc = bc;
      const l = customFoods(); l.unshift(f); store.set('foods', l); closeSheet(); fa.tab = 'my'; fa.q = ''; viewFoodAdd(); openPortion(f.id);
    };
  });
}
function openQuick() {
  nSheet(`<h3>Только калории</h3>
    <div class="opt"><div>Название</div><input id="qn" class="tin wide" type="text" placeholder="Необязательно" autocomplete="off"></div>
    <div class="opt"><div>Калории</div><div class="nin"><input id="qk" type="number" inputmode="decimal"><span>ккал</span></div></div>
    <div class="opt"><div>Белки</div><div class="nin"><input id="qp" type="number" inputmode="decimal" placeholder="0"><span>г</span></div></div>
    <div class="opt"><div>Жиры</div><div class="nin"><input id="qf" type="number" inputmode="decimal" placeholder="0"><span>г</span></div></div>
    <div class="opt"><div>Углеводы</div><div class="nin"><input id="qc" type="number" inputmode="decimal" placeholder="0"><span>г</span></div></div>
    <button class="big" id="qok">Добавить</button>`, () => {
    $('#qok').onclick = () => { const k = pn($('#qk').value); if (!(k > 0)) { $('#qk').focus(); return; } addEntry({ fid: '', name: $('#qn').value.trim() || 'Быстрая запись', g: 0, b: null, k: Math.round(k), p: r1(pn($('#qp').value)), f: r1(pn($('#qf').value)), c: r1(pn($('#qc').value)) }); closeSheet(); };
  });
}

function foodBackup() {
  const o = { nut: nutCfg(), foods: customFoods(), ffav: store.get('ffav', []), sup: supList(), tpl: tplList(), supd: {}, days: {}, water: {}, steps: {}, sleep: {} };
  try { for (let i = 0; i < localStorage.length; i++) { const k = localStorage.key(i); if (k && k.startsWith('tr:food:')) o.days[k.slice(8)] = JSON.parse(localStorage.getItem(k)); if (k && k.startsWith('tr:fsu:')) o.supd[k.slice(7)] = JSON.parse(localStorage.getItem(k)); if (k && k.startsWith('tr:fw:')) o.water[k.slice(6)] = JSON.parse(localStorage.getItem(k)); if (k && k.startsWith('tr:fs:')) o.steps[k.slice(6)] = JSON.parse(localStorage.getItem(k)); if (k && k.startsWith('tr:fz:')) o.sleep[k.slice(6)] = JSON.parse(localStorage.getItem(k)); } } catch (e) { }
  return o;
}
function foodRestore(o) {
  if (!o || typeof o !== 'object') return;
  if (o.nut) store.set('nut', o.nut); if (Array.isArray(o.foods)) store.set('foods', o.foods); if (Array.isArray(o.ffav)) store.set('ffav', o.ffav);
  if (Array.isArray(o.sup)) store.set('sup', o.sup); if (Array.isArray(o.tpl)) store.set('ftpl', o.tpl);
  Object.entries(o.supd || {}).forEach(([k, v]) => { if (v && typeof v === 'object') store.set('fsu:' + k, v); });
  Object.entries(o.days || {}).forEach(([k, v]) => { if (Array.isArray(v)) saveLog(k, v); });
  Object.entries(o.water || {}).forEach(([k, v]) => { if (v >= 0) store.set('fw:' + k, v); });
  Object.entries(o.steps || {}).forEach(([k, v]) => { if (v >= 0) store.set('fs:' + k, v); });
  Object.entries(o.sleep || {}).forEach(([k, v]) => { if (v >= 0) store.set('fz:' + k, v); });
}

const WI = {
  pill: '<svg viewBox="0 0 24 24"><rect x="3" y="8.5" width="18" height="7" rx="3.5" transform="rotate(-35 12 12)"/><path d="M9.2 8.6l5.6 6.8"/></svg>',
  check: '<svg viewBox="0 0 24 24"><path d="M5 12.5l4.5 4.5L19 7.5"/></svg>',
  body: '<svg viewBox="0 0 24 24"><rect x="4" y="3" width="16" height="18" rx="4"/><path d="M8.5 8.5h7M12 8.5v3"/></svg>',
  drop: '<svg viewBox="0 0 24 24"><path d="M12 3c4 5 6 8 6 11a6 6 0 01-12 0c0-3 2-6 6-11z"/></svg>',
  flame: '<svg viewBox="0 0 24 24"><path d="M12 3c1 4 5 6 5 11a5 5 0 01-10 0c0-2 1-3 2-4 0 2 1 3 2 3 0-3-1-6 1-10z"/></svg>',
  target: '<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="3.5"/><path d="M12 2v3M22 12h-3"/></svg>',
  down: '<svg viewBox="0 0 24 24"><path d="M6 9l6 6 6-6"/></svg>',
  sleep: '<svg viewBox="0 0 24 24"><path d="M20 14.5A8 8 0 019.5 4a8 8 0 1010.5 10.5z"/></svg>',
  steps: '<svg viewBox="0 0 24 24"><path d="M8 4c2 0 3 1.5 3 4s-1 4-3 4-3-1.5-3-4 1-4 3-4zM6 15h5v2.5a1.5 1.5 0 01-1.5 1.5h-2A1.5 1.5 0 016 17.5zM16 8c2 0 3 1.5 3 4s-1 4-3 4-3-1.5-3-4 1-4 3-4zM14 19h5"/></svg>',
  fem: '<svg viewBox="0 0 24 24"><circle cx="12" cy="9" r="5"/><path d="M12 14v8M8.5 18h7"/></svg>',
  mal: '<svg viewBox="0 0 24 24"><circle cx="10" cy="14" r="5.5"/><path d="M14 10l6-6M15 4h5v5"/></svg>'
};
const LB = 2.20462, CM_IN = 2.54;
const MONTHS_G = ['января', 'февраля', 'марта', 'апреля', 'мая', 'июня', 'июля', 'августа', 'сентября', 'октября', 'ноября', 'декабря'];
const fmtH = (h, u) => { if (u === 'imp') { const t = Math.round(h / CM_IN); return Math.floor(t / 12) + ' фт ' + (t % 12) + ' дюйм.'; } return num(r1(h)) + ' см'; };
const fmtW = (w, u) => u === 'imp' ? num(r1(w * LB)) + ' фнт' : num(r1(w)) + ' кг';
const fmtB = b => b ? b.split('-').reverse().join('.') : '';
const ageOf = b => { if (!b) return 0; const [y, m, d] = b.split('-').map(Number), t = new Date(); let a = t.getFullYear() - y; if (t.getMonth() + 1 < m || (t.getMonth() + 1 === m && t.getDate() < d)) a--; return a; };
const range = (a, b) => Array.from({ length: b - a + 1 }, (_, i) => a + i);

function openWheel(title, cols, btn, done) {
  openSheet(`<div class="grab"></div><div class="whd"><h3>${esc(title)}</h3><button class="wx" id="wxc" aria-label="Закрыть">${I.close}</button></div>
    <div class="wheel"><div class="wband"></div>${cols.map((c, i) => `<div class="wcol" style="flex:${c.flex || 1}">${c.items.map(t => `<div class="wi">${esc(t)}</div>`).join('')}</div>`).join('')}</div>
    <button class="big" id="wok">${btn}</button>`, () => {
    const els = [...document.querySelectorAll('.wcol')], H = 48;
    const idx = el => Math.max(0, Math.min(el.children.length - 1, Math.round(el.scrollTop / H)));
    const paint = el => { const f = el.scrollTop / H; [...el.children].forEach((it, i) => { const d = Math.abs(i - f); it.style.opacity = Math.max(.12, 1 - d * .42); it.style.transform = `scale(${Math.max(.72, 1 - d * .1)})`; }); };
    els.forEach((el, i) => { el.scrollTop = cols[i].idx * H; paint(el); el.onscroll = () => paint(el); el.onclick = e => { const it = e.target.closest('.wi'); if (it) el.scrollTo({ top: [...el.children].indexOf(it) * H, behavior: 'smooth' }); }; });
    $('#wxc').onclick = closeSheet;
    $('#wok').onclick = () => { const r = els.map(idx); closeSheet(); done(r); };
  });
}

let wz = null;
function nutWizard(edit) {
  const P = profile(), C = nutCfg(), d = P.goal - P.w;
  wz = { s: 0, edit, name: C.name || '', chef: !!C.chef, gt: C.goalType || (d <= -2 ? 'lose' : d >= 2 ? 'gain' : 'keep'), gender: P.gender, u: C.units || 'met', birth: C.birth || '', h: P.h, w: P.w, gw: P.goal, act: P.act || 0, pace: C.pace || '' };
  wzDraw();
}
const wzPaces = () => wz.gt === 'lose' ? ['l10', 'l15', 'l20'] : wz.gt === 'gain' ? ['g10'] : ['keep'];
const wzPace = () => wzPaces().includes(wz.pace) ? wz.pace : (wz.gt === 'lose' ? 'l15' : wz.gt === 'gain' ? 'g10' : 'keep');
const wzProf = () => Object.assign({}, profile(), { gender: wz.gender, h: wz.h, w: wz.w, goal: wz.gt === 'keep' ? wz.w : wz.gw, act: wz.act });

function wzDraw() {
  const s = wz.s, ic = ['check', 'body', 'drop', 'flame', 'target'], last = s === 4;
  const steps = `<div class="wsteps">${ic.map((k, i) => `${i ? `<i class="wsl ${i <= s ? 'on' : ''}"></i>` : ''}<span class="wsd ${i < s ? 'done' : i === s ? 'cur' : ''}">${i < s ? WI.check : WI[k]}</span>`).join('')}</div>`;
  const row = (k, lab, val, ph) => `<div class="wlab">${lab}</div><button class="wrow ${val ? '' : 'ph'}" data-wr="${k}"><span>${val || ph || ''}</span>${['u'].includes(k) ? WI.down : ''}</button>`;
  let h = '';
  if (s === 0) {
    h = `<h2>Давай настроим питание</h2><p>Выбери цель, а мы рассчитаем норму калорий и БЖУ</p>
      <div class="wlab" style="margin-top:0">Как тебя зовут</div><input id="wname" class="wrow wtxt" type="text" maxlength="30" placeholder="Необязательно" autocomplete="off" value="${esc(wz.name)}">
      <div class="wlab">Цель</div>
      <div class="wlist">${[['lose', 'Похудеть', 'небольшой дефицит калорий'], ['keep', 'Держать вес', 'есть столько, сколько тратишь'], ['gain', 'Набрать массу', 'небольшой профицит калорий']].map(([k, t, d]) => `<button class="wopt ${wz.gt === k ? 'on' : ''}" data-wg="${k}"><div><b>${t}</b><small>${d}</small></div><span class="wrad"></span></button>`).join('')}</div>`;
  } else if (s === 1) {
    h = `<h2>${wz.name ? 'Приятно познакомиться, ' + esc(wz.name) + '!' : 'Основные данные'}</h2><p>Начнём с основных данных, чтобы создать персональные рекомендации</p>
      <div class="wlab">Пол</div><div class="wgen">${[['female', 'Женский', WI.fem], ['male', 'Мужской', WI.mal]].map(([k, t, i]) => `<button class="${wz.gender === k ? 'on' : ''}" data-wgd="${k}">${i}${t}</button>`).join('')}</div>
      ${row('u', 'Единицы измерения', wz.u === 'imp' ? 'фнт · дюйм.' : 'кг · см')}
      ${row('b', 'Дата рождения', fmtB(wz.birth), 'ДД.ММ.ГГГГ')}
      ${row('h', 'Рост', fmtH(wz.h, wz.u))}
      ${row('w', 'Вес', fmtW(wz.w, wz.u))}`;
  } else if (s === 2) {
    const dl = r1(wz.gw - wz.w);
    h = `<h2>${wz.gt === 'keep' ? 'Твой вес' : 'Желаемый вес'}</h2><p>${wz.gt === 'keep' ? 'Будем держать текущий вес' : 'К какому весу ты хочешь прийти'}</p>
      ${wz.gt === 'keep' ? row('w', 'Вес', fmtW(wz.w, wz.u)) : row('g', 'Желаемый вес', fmtW(wz.gw, wz.u))}
      ${wz.gt === 'keep' ? '' : `<div class="note">${dl === 0 ? 'Желаемый вес равен текущему.' : (dl < 0 ? 'Нужно сбросить ' : 'Нужно набрать ') + fmtW(Math.abs(dl), wz.u) + '.'}${wz.gt === 'lose' && dl > 0 || wz.gt === 'gain' && dl < 0 ? ' Проверь: цель и вес не совпадают.' : ''}</div>`}`;
  } else if (s === 3) {
    h = `<h2>Насколько ты активен?</h2><p>Повседневная активность без учёта тренировок</p>
      <div class="wlist">${ACTS.map((t, i) => `<button class="wopt ${wz.act === i ? 'on' : ''}" data-wa="${i}"><div><b>${esc(t)}</b></div><span class="wrad"></span></button>`).join('')}</div>`;
  } else {
    const P = wzProf(), age = ageOf(wz.birth) || 25, pc = wzPace();
    const opts = wzPaces().map(k => { const o = nutPace.find(x => x[0] === k), g = nutGoal(P, { age, pace: k, kcal: 0, chef: wz.chef }); return `<button class="wopt ${pc === k ? 'on' : ''}" data-wp="${k}"><div><b>${o[1]}</b><small>${o[2]}</small></div><em>${fmt0(g.kcal)}<small>ккал</small></em></button>`; }).join('');
    h = `<h2>${wz.gt === 'lose' ? 'Выбери темп' : 'Твоя норма'}</h2><p>Норма калорий на день по формуле Миффлина-Сан Жеора</p><div class="wlist">${opts}</div>
      <div class="wlist" style="margin-top:10px"><button class="wopt ${wz.chef ? 'on' : ''}" id="wchef"><div><b>Щедрый повар</b><small>плюс 10% к норме: запас на порции «на глаз» <span class="chq" data-chefi>Что это?</span></small></div><span class="wrad"></span></button></div>${bodyFat(P, age) ? `<div class="note" style="margin:12px 0 0">Оценка процента жира: около ${num(bodyFat(P, age))}%. Это ориентир по формуле Деуренберга, погрешность до 5%.</div>` : ''}`;
  }
  view(`<div class="screen wz">${steps}${h}<div class="wfoot"><button class="big" id="wnext">${last ? 'Готово' : 'Далее'}</button>${last ? '<button class="link" id="wmore">Ещё настройки</button>' : ''}<button class="link" id="wback">${s ? 'Назад' : wz.edit || sessionStorage.getItem('tr-nut') ? 'Отмена' : 'Пропустить'}</button></div></div>`);
  if ($('#wmore')) $('#wmore').onclick = () => openNutSetup(false);
  $('#wback').onclick = () => { if (s) { wz.s--; wzDraw(); } else { wz = null; viewFood(); } };
  if ($('#wname')) $('#wname').oninput = e => { wz.name = e.target.value.trim(); };
  document.querySelectorAll('[data-wg]').forEach(b => b.onclick = () => { wz.gt = b.dataset.wg; wz.pace = ''; if (wz.gt === 'keep') wz.gw = wz.w; else if (Math.abs(wz.gw - wz.w) < 1) wz.gw = Math.max(30, Math.round(wz.w + (wz.gt === 'lose' ? -5 : 5))); wzDraw(); });
  document.querySelectorAll('[data-wgd]').forEach(b => b.onclick = () => { wz.gender = b.dataset.wgd; wzDraw(); });
  document.querySelectorAll('[data-wa]').forEach(b => b.onclick = () => { wz.act = +b.dataset.wa; wzDraw(); });
  if ($('#wchef')) $('#wchef').onclick = () => { wz.chef = !wz.chef; wzDraw(); };
  document.querySelectorAll('[data-wp]').forEach(b => b.onclick = () => { wz.pace = b.dataset.wp; wzDraw(); });
  document.querySelectorAll('[data-wr]').forEach(b => b.onclick = () => wzWheel(b.dataset.wr));
  $('#wnext').onclick = () => {
    if (s === 1) { const a = ageOf(wz.birth); if (!(a >= 10 && a <= 100)) { wzWheel('b'); return; } }
    if (!last) { wz.s++; wzDraw(); return; }
    const P = wzProf(), age = ageOf(wz.birth), pace = wzPace(), pr = store.get('profile', {});
    Object.assign(pr, { gender: P.gender, h: P.h, w: P.w, goal: P.goal, act: P.act }); store.set('profile', pr);
    store.set('nut', Object.assign({}, nutCfg(), { age, birth: wz.birth, units: wz.u, goalType: wz.gt, pace, kcal: 0, name: wz.name, chef: wz.chef }));
    wz = null; try { sessionStorage.setItem('tr-nut', '1'); } catch (e) { }
    viewFood(); toast('Норма готова', fmt0(nutGoal().kcal) + ' ккал в день');
  };
}
function wzWheel(k) {
  const u = wz.u;
  if (k === 'u') return openSheet(`<div class="grab"></div><div class="whd"><h3>Единицы измерения</h3><button class="wx" id="wxc" aria-label="Закрыть">${I.close}</button></div>
    <div class="wlist in">${[['met', 'Метрические', 'кг · см · км · мл'], ['imp', 'Имперские', 'фнт · дюйм. · ми · жидк. унц.']].map(([v, t, d]) => `<button class="wopt ${u === v ? 'on' : ''}" data-uu="${v}"><div><b>${t}</b><small>${d}</small></div><span class="wrad"></span></button>`).join('')}</div>
    <button class="big" id="wok">Сохранить</button>`, () => {
    let cur = u; $('#wxc').onclick = closeSheet;
    document.querySelectorAll('[data-uu]').forEach(b => b.onclick = () => { cur = b.dataset.uu; document.querySelectorAll('[data-uu]').forEach(x => x.classList.toggle('on', x === b)); });
    $('#wok').onclick = () => { wz.u = cur; closeSheet(); wzDraw(); };
  });
  if (k === 'b') {
    const t = new Date(), y0 = t.getFullYear(), cur = wz.birth ? wz.birth.split('-').map(Number) : [y0 - 30, 1, 1], ys = range(y0 - 100, y0 - 10);
    return openWheel('Дата рождения', [{ items: range(1, 31).map(String), idx: cur[2] - 1, flex: .7 }, { items: MONTHS_G, idx: cur[1] - 1, flex: 1.3 }, { items: ys.map(String), idx: ys.indexOf(cur[0]) < 0 ? 70 : ys.indexOf(cur[0]), flex: 1 }], 'Далее', r => {
      const y = ys[r[2]], m = r[1] + 1, d = Math.min(r[0] + 1, new Date(y, m, 0).getDate());
      wz.birth = y + '-' + String(m).padStart(2, '0') + '-' + String(d).padStart(2, '0'); wzDraw();
    });
  }
  if (k === 'h') return heightWheel(wz.h, u, v => { wz.h = v; wzDraw(); });
  const key = k === 'g' ? 'gw' : 'w';
  weightWheel(k === 'g' ? 'Желаемый вес' : 'Вес', wz[key], u, v => { wz[key] = v; wzDraw(); });
}
function heightWheel(h, u, cb) {
  if (u === 'imp') { const t = Math.round(h / CM_IN), f = Math.floor(t / 12), i = t % 12; return openWheel('Рост', [{ items: range(3, 8).map(x => x + ' фт'), idx: Math.max(0, Math.min(5, f - 3)) }, { items: range(0, 11).map(x => x + ' дюйм.'), idx: i }], 'Далее', r => cb(r1((((r[0] + 3) * 12) + r[1]) * CM_IN))); }
  const cm = Math.floor(h), mm = h - cm >= .5 ? 1 : 0, cs = range(120, 230);
  openWheel('Рост', [{ items: cs.map(x => x + ' см'), idx: Math.max(0, Math.min(cs.length - 1, cm - 120)), flex: 1.6 }, { items: ['0 мм', '5 мм'], idx: mm }], 'Далее', r => cb(cs[r[0]] + r[1] * .5));
}
function weightWheel(ttl, v, u, cb) {
  if (u === 'imp') { const lb = v * LB, a = Math.floor(lb), b = Math.min(9, Math.round((lb - a) * 10)), ls = range(66, 550); return openWheel(ttl, [{ items: ls.map(x => x + ' фнт'), idx: Math.max(0, Math.min(ls.length - 1, a - 66)), flex: 1.6 }, { items: range(0, 9).map(x => ',' + x), idx: b }], 'Далее', r => cb(r1((ls[r[0]] + r[1] / 10) / LB))); }
  const kg = Math.floor(v), g = Math.min(9, Math.round((v - kg) * 10)), ks = range(30, 250);
  openWheel(ttl, [{ items: ks.map(x => x + ' кг'), idx: Math.max(0, Math.min(ks.length - 1, kg - 30)), flex: 1.6 }, { items: range(0, 9).map(x => x * 100 + ' г'), idx: g }], 'Далее', r => cb(ks[r[0]] + r[1] / 10));
}

function openSteps() {
  nSheet(`<h3>Шаги</h3><div class="pbig"><b id="sv">0</b><small>шагов</small><div id="sg"></div></div>
    <div class="wq">${[500, 1000, 2000, 5000].map(x => `<button data-sq="${x}">+${x}</button>`).join('')}</div>
    <div class="opt"><div>Ввести точно</div><div class="nin"><input id="sx" type="number" inputmode="numeric" placeholder="0"><span>шагов</span></div></div>
    <div class="wq"><button id="sset">Записать число</button><button id="sz">Сбросить</button></div>
    <button class="big" id="sdone">Готово</button>`, () => {
    const show = () => { const v = stepsDay(fdate); $('#sv').textContent = fmt0(v); $('#sg').textContent = 'цель ' + fmt0(STEP_GOAL) + ' · примерно ' + fmt0(stepKcal(v)) + ' ккал'; };
    show();
    document.querySelectorAll('[data-sq]').forEach(b => b.onclick = () => { store.set('fs:' + fdate, stepsDay(fdate) + +b.dataset.sq); show(); });
    $('#sset').onclick = () => { const v = Math.round(pn($('#sx').value)); if (v > 0) { store.set('fs:' + fdate, v); $('#sx').value = ''; show(); } };
    $('#sz').onclick = () => { store.set('fs:' + fdate, 0); show(); };
    $('#sdone').onclick = () => { closeSheet(); viewFood(true); };
  });
}

function openCopy(list) {
  const t = fkey(new Date());
  nSheet(`<h3>Копировать в день</h3>
    <div class="wq">${[['Вчера', -1], ['Сегодня', 0], ['Завтра', 1]].map(([x, d]) => `<button data-cp="${shiftDay(t, d)}">${x}</button>`).join('')}</div>
    <div class="opt"><input type="date" id="cpd" class="dateinp" value="${shiftDay(t, 0)}"></div>
    <button class="big" id="cpok">Копировать</button>`, () => {
    const go_ = key => {
      const l = dayLog(key), base = fdateObj(key).getTime() + 12 * 3600e3 + l.length;
      list.forEach((e, i) => l.push(Object.assign({}, e, { id: Date.now() + '' + i + Math.floor(Math.random() * 1000), ts: base + i })));
      saveLog(key, l); closeSheet(); toast('Скопировано', dayLabel(key) + ': ' + list.length + ' ' + (list.length === 1 ? 'запись' : 'записей'));
    };
    document.querySelectorAll('[data-cp]').forEach(b => b.onclick = () => go_(b.dataset.cp));
    $('#cpok').onclick = () => { const v = $('#cpd').value; if (v) go_(v); };
  });
}

function viewMeal(keep) {
  if (!fdate) fdate = fkey(new Date());
  const y = keep ? window.scrollY : 0, m = fa.meal, l = dayLog(fdate).filter(e => m === 4 ? isDrink(e) : e.meal === m).sort((a, b) => a.ts - b.ts), S = sumLog(l), G = nutGoal();
  const share = G.kcal ? Math.round(S.k / G.kcal * 100) : 0;
  view(`<div class="screen has-nav">
    <div class="bar"><button class="rbtn" id="mback" aria-label="Назад">${I.back}</button><h1>${MEALS[m]}<small>${esc(dayLabel(fdate))}</small></h1><span class="rbtn ghost"></span></div>
    <div class="fcard msum"><div class="mi big2">${MEAL_IC[m]}</div><div class="mk"><b>${fmt0(S.k)}</b><small>ккал${S.k ? ' · ' + share + '% нормы дня' : ''}</small></div></div>
    <div class="stat3 mmac"><div><b>${num(r1(S.p))}</b><small>белки, г</small></div><div><b>${num(r1(S.f))}</b><small>жиры, г</small></div><div><b>${num(r1(S.c))}</b><small>углеводы, г</small></div></div>
    ${l.length ? `<div class="flog" style="margin-top:14px">${l.map(e => `<button class="fe" data-fe="${e.id}"><span class="mi sm">${MEAL_IC[e.meal]}</span><div><b>${esc(e.name)}</b><small>${m === 4 && e.meal !== 4 ? MEALS[e.meal] + ' · ' : ''}${e.g ? fmt0(e.g) + ' г · ' : ''}Б ${num(r1(e.p))} · Ж ${num(r1(e.f))} · У ${num(r1(e.c))}</small></div><em>${fmt0(e.k)}<small>ккал</small></em></button>`).join('')}</div>` : '<div class="empty small">В этом приёме пока пусто.</div>'}
    <div class="mact"><button class="big" id="madd">Добавить</button>${l.length ? '<button class="big sec" id="mcp">Копировать приём пищи</button>' : ''}<button class="big sec" id="mtp">Шаблоны</button></div>
    ${nav('food')}</div>`);
  if (keep) window.scrollTo(0, y);
  $('#mback').onclick = () => goBack('#food');
  $('#madd').onclick = () => { fa.tab = 'pop'; fa.q = ''; go('#fadd'); };
  if ($('#mcp')) $('#mcp').onclick = () => openCopy(l);
  $('#mtp').onclick = openTpl;
  document.querySelectorAll('[data-fe]').forEach(b => b.onclick = () => openEntry(b.dataset.fe));
}

function openSleep() {
  const v0 = sleepDay(fdate) || SLEEP_GOAL;
  openWheel('Сон', [{ items: range(0, 14).map(x => x + ' ч'), idx: Math.floor(v0 / 60) }, { items: range(0, 11).map(x => x * 5 + ' мин'), idx: Math.round((v0 % 60) / 5) }], 'Записать', r => { store.set('fz:' + fdate, r[0] * 60 + r[1] * 5); viewFood(true); toast('Сон записан', fmtSleep(r[0] * 60 + r[1] * 5)); });
}

document.addEventListener('click', e => { if (e.target.closest('[data-chefi]')) { e.stopPropagation(); e.preventDefault(); openChefInfo(); } }, true);
function openChefInfo() {
  nSheet(`<h3>Щедрый повар</h3><div class="chinf"><div class="chi"><svg viewBox="0 0 24 24"><path d="M7 16c-2.5 0-4-2-4-4s1.800-4 4-4c.5-2 2.500-3 5-3s4.500 1 5 3c2.200 0 4 2 4 4s-1.500 4-4 4M7 16v4h10v-4M7 18.500h10M10 16v2M14 16v2"/></svg></div><h4>Что такое щедрый повар?</h4><p>Режим добавляет к дневной норме <b>10% калорий</b>.</p><hr><p>В кафе и ресторанах кладут больше масла и сливок, чем по рецепту, поэтому порции калорийнее, чем кажется.</p><hr><p><b>Отказываться от кафе и встреч не нужно: этот режим помогает их учесть.</b></p></div><button class="big" id="chok">Понятно!</button>`, () => { $('#chok').onclick = closeSheet; });
}
